
-- Surface Inject Animation
local function _SurfaceBootAnim()
    local ok, gui = pcall(function()
        local sg = Instance.new("ScreenGui")
        sg.Name = "SurfaceBoot"
        sg.ResetOnSpawn = false
        sg.DisplayOrder = 999
        sg.IgnoreGuiInset = true
        pcall(function() sg.Parent = game:GetService("CoreGui") end)
        if not sg.Parent then sg.Parent = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui") end

        local bg = Instance.new("Frame", sg)
        bg.Size = UDim2.new(1,0,1,0)
        bg.BackgroundColor3 = Color3.fromRGB(5,5,8)
        bg.BorderSizePixel = 0
        bg.BackgroundTransparency = 1

        local title = Instance.new("TextLabel", bg)
        title.Size = UDim2.new(0,500,0,60)
        title.Position = UDim2.new(0.5,-250,0.5,-80)
        title.BackgroundTransparency = 1
        title.Text = "Surface"
        title.Font = Enum.Font.GothamBold
        title.TextSize = 52
        title.TextColor3 = Color3.fromRGB(255,255,255)
        title.TextTransparency = 1

        local sub = Instance.new("TextLabel", bg)
        sub.Size = UDim2.new(0,500,0,30)
        sub.Position = UDim2.new(0.5,-250,0.5,-20)
        sub.BackgroundTransparency = 1
        sub.Text = "loading modules..."
        sub.Font = Enum.Font.Gotham
        sub.TextSize = 18
        sub.TextColor3 = Color3.fromRGB(120,120,140)
        sub.TextTransparency = 1

        local barBg = Instance.new("Frame", bg)
        barBg.Size = UDim2.new(0,400,0,3)
        barBg.Position = UDim2.new(0.5,-200,0.5,30)
        barBg.BackgroundColor3 = Color3.fromRGB(30,30,40)
        barBg.BorderSizePixel = 0
        barBg.BackgroundTransparency = 1
        Instance.new("UICorner", barBg).CornerRadius = UDim.new(1,0)

        local bar = Instance.new("Frame", barBg)
        bar.Size = UDim2.new(0,0,1,0)
        bar.BackgroundColor3 = Color3.fromRGB(100,180,255)
        bar.BorderSizePixel = 0
        Instance.new("UICorner", bar).CornerRadius = UDim.new(1,0)

        local version = Instance.new("TextLabel", bg)
        version.Size = UDim2.new(0,500,0,20)
        version.Position = UDim2.new(0.5,-250,0.5,50)
        version.BackgroundTransparency = 1
        version.Text = "v1 beta"
        version.Font = Enum.Font.Gotham
        version.TextSize = 13
        version.TextColor3 = Color3.fromRGB(60,60,80)
        version.TextTransparency = 1

        -- fade in
        local TweenService = game:GetService("TweenService")
        local ti = TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        TweenService:Create(bg, ti, {BackgroundTransparency=0}):Play()
        TweenService:Create(title, ti, {TextTransparency=0}):Play()
        task.wait(0.15)
        TweenService:Create(sub, TweenInfo.new(0.3), {TextTransparency=0}):Play()
        TweenService:Create(barBg, TweenInfo.new(0.3), {BackgroundTransparency=0}):Play()
        TweenService:Create(version, TweenInfo.new(0.3), {TextTransparency=0}):Play()

        -- progress bar sweep
        local steps = {"resolving services","hooking modules","building ui","finalizing"}
        for i, s in ipairs(steps) do
            sub.Text = s .. "..."
            TweenService:Create(bar, TweenInfo.new(0.35, Enum.EasingStyle.Quad), {Size=UDim2.new(i/#steps,0,1,0)}):Play()
            task.wait(0.38)
        end
        bar.BackgroundColor3 = Color3.fromRGB(80,255,160)
        sub.Text = "ready"
        task.wait(0.4)

        -- fade out
        local tout = TweenInfo.new(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
        TweenService:Create(bg, tout, {BackgroundTransparency=1}):Play()
        TweenService:Create(title, tout, {TextTransparency=1}):Play()
        TweenService:Create(sub, tout, {TextTransparency=1}):Play()
        TweenService:Create(barBg, tout, {BackgroundTransparency=1}):Play()
        TweenService:Create(version, tout, {TextTransparency=1}):Play()
        task.wait(0.55)
        sg:Destroy()
    end)
end
task.spawn(_SurfaceBootAnim)
task.wait(0.1)


